      {result && (
        <p>
          Claims changed: <strong data-testid="rate-preview-count">{result.count}</strong>, difference:{' '}
          <strong data-testid="rate-preview-diff">{result.diff}</strong>
        </p>
      )}
      {error && (
        <p role="alert" data-testid="rate-preview-error">
          {error}
        </p>
      )}
